{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "A 20% cap is not inherently unacceptable, but should not govern title, tax or specific indemnities merely by default."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek lower thresholds and a tipping basket."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a period allowing review through a meaningful post-Completion reporting/audit cycle."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Seek recovery up to at least the full purchase price and materially longer survival, with appropriate remedies and fraud protection."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Require express protection for fraud, fraudulent misrepresentation and deliberate concealment, and preserve liabilities that cannot lawfully be excluded."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket data-room disclosure"
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer deleting the exclusion."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make effective change-of-control consent a condition precedent, waivable only by the Buyer."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require effective releases of relevant security, guarantees and lender claims at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Agree that sale-triggered bonuses are Seller transaction expenses or another express Seller-funded deduction."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Retain a specific indemnity for losses arising from the pre-Completion payment/title defect, including appropriate third-party claims, remediation and defence costs."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for the pre-Completion incident and resulting liabilities and reasonable response costs, with appropriate survival."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Depending on the evidence, they may be ordinary post-Completion expenses, working-capital items, pre-Completion liabilities or Seller-funded commitments."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Separate general warranty, title, tax and specific-indemnity regimes; reject limitations applying indiscriminately to all claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is useful evidence, but the share register alone is not sufficient transaction protection."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Require a separate tax covenant/indemnity for relevant pre-Completion tax liabilities, supported by warranties."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

